-- Lean & Fit - Reseller Portal: real Philippine geography for territory
-- selection, replacing free-text region/city/barangay on both onboarding
-- routes with a live, capacity-checked picker. See supabase/README.md's
-- "Migration 0012" section for the full design writeup. Paste after
-- 0002-0011.
--
-- Source data: philippine-regions-provinces-cities-municipalities-barangays
-- (2019v2), github.com/flores-jacob/philippine-regions-provinces-cities-
-- municipalities-barangays - 17 regions, 86 provinces, 1,647 cities/
-- municipalities, 42,042 barangays.
--
-- Scope decision: importing all ~43,700 rows (region+province+city+
-- barangay) directly would make this migration file impractically large
-- to paste into the Supabase SQL editor (province name collisions across
-- 25 real city names within the same region rule out flattening province
-- out of the hierarchy - confirmed against the source data, not assumed).
-- Instead:
--   - region + province + city (~1,750 rows) are seeded here directly -
--     these are the levels Franchise/Distributor actually occupy, plus
--     the disambiguating province layer, and 1,750 rows is a reasonable
--     migration size.
--   - barangay names ship as a static bundled frontend asset
--     (public/data/ph-barangays.json, keyed by city territory id) for the
--     picker's OPTIONS - no DB row needed just to list them.
--   - an actual `territories` row for a specific barangay (the level
--     Reseller occupies, where capacity actually matters) is created
--     lazily, the first time anyone picks it on either onboarding route -
--     find_or_create_barangay_territory() below. Most of the 42,042
--     barangays will never need a row; the ones that do get created
--     on-demand with capacity = null (unlimited) until an admin caps one.

alter type territory_level add value 'province';

-- The public application form (Route A, anon) now shows live capacity too
-- (spec §19, finally closed for both onboarding routes) - migration 0011
-- only granted this to `authenticated` since only Route B needed it then.
grant execute on function list_territories_with_occupancy to anon;
-- Auto-generated PH region/province/city seed data.
-- Source: philippine-regions-provinces-cities-municipalities-barangays (2019v2),
-- github.com/flores-jacob/philippine-regions-provinces-cities-municipalities-barangays
-- Deterministic UUIDs (uuid5) so this file is idempotent to re-run and so the
-- companion frontend asset (public/data/ph-barangays.json) can reference city ids
-- directly without a round trip.

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;
-- ---------------------------------------------------------------------
-- find_or_create_barangay_territory(): the lazy-creation path described
-- above. Matches case-insensitively against the picked name (bundled
-- asset names are already the authoritative PSGC spelling, but this
-- guards against any client-side normalization drift) so the same
-- barangay is never accidentally created twice under one city.
-- ---------------------------------------------------------------------

create or replace function find_or_create_barangay_territory(
  p_name text,
  p_city_territory_id uuid
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  select territories.id into v_id
  from territories
  where territories.level = 'barangay'
    and territories.parent_id = p_city_territory_id
    and upper(territories.name) = upper(trim(p_name))
  limit 1;

  if v_id is not null then
    return v_id;
  end if;

  values ('barangay', trim(p_name), p_city_territory_id, null)
  returning territories.id into v_id;

  return v_id;
end;
$$;

grant execute on function find_or_create_barangay_territory to anon, authenticated;

-- ---------------------------------------------------------------------
-- describe_territory_chain(): given any territory, walks up to region
-- and returns the region/city/barangay name triple - whichever apply
-- given the starting level, the rest null. Used to populate the
-- `partners` table's free-text region/city/barangay display columns
-- (unchanged shape, spec §16) regardless of which level was actually
-- picked or which onboarding route created the row. Province is
-- intentionally not returned - it's structural only, never shown.
-- ---------------------------------------------------------------------

create or replace function describe_territory_chain(p_territory_id uuid)
returns table (region_name text, city_name text, barangay_name text)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_cursor_id uuid := p_territory_id;
  v_cursor_level territory_level;
  v_cursor_name text;
  v_cursor_parent uuid;
  v_region text;
  v_city text;
  v_barangay text;
begin
  loop
    select territories.level, territories.name, territories.parent_id
      into v_cursor_level, v_cursor_name, v_cursor_parent
    from territories where territories.id = v_cursor_id;

    exit when v_cursor_level is null;

    if v_cursor_level = 'region' then v_region := v_cursor_name;
    elsif v_cursor_level = 'city' then v_city := v_cursor_name;
    elsif v_cursor_level = 'barangay' then v_barangay := v_cursor_name;
    end if;

    exit when v_cursor_level = 'region' or v_cursor_parent is null;
    v_cursor_id := v_cursor_parent;
  end loop;

  return query select v_region, v_city, v_barangay;
end;
$$;

grant execute on function describe_territory_chain to anon, authenticated;

-- ---------------------------------------------------------------------
-- territory_ancestor_region_id(): walks up to the enclosing region's id
-- (not name) - used by onboard_partner()'s containment check (spec §28)
-- to confirm a Franchise sponsor's own region actually encloses the city
-- they're onboarding into, regardless of how many levels (province, now)
-- sit in between.
-- ---------------------------------------------------------------------

create or replace function territory_ancestor_region_id(p_territory_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  with recursive chain as (
    select territories.id, territories.level, territories.parent_id
    from territories where territories.id = p_territory_id
    union all
    select t.id, t.level, t.parent_id
    from territories t join chain c on t.id = c.parent_id
  )
  select id from chain where level = 'region' limit 1;
$$;

grant execute on function territory_ancestor_region_id to anon, authenticated;

-- ---------------------------------------------------------------------
-- resolve_and_reserve_territory(): shared by apply_for_partner() (Route
-- A) and onboard_partner() (Route B) - given a partner_type and the
-- territory the applicant/sponsor picked, resolves the FINAL territory
-- the new partner will occupy (the input itself for Franchise/
-- Distributor, since region/city are pre-seeded and picked directly; a
-- lazily-created barangay for Reseller, since p_input_territory_id for a
-- Reseller is the PARENT city, not the barangay itself - the picker
-- can't offer a barangay id that may not exist in the DB yet) and
-- enforces spec §29's capacity check on that final territory. Does NOT
-- check onboarding permissions or territorial containment - Route A has
-- neither concept (no sponsor), Route B layers both on top separately
-- since they depend on the calling partner, not just the target.
-- ---------------------------------------------------------------------

create or replace function resolve_and_reserve_territory(
  p_partner_type partner_type,
  p_input_territory_id uuid,
  p_barangay_name text
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_input_level territory_level;
  v_capacity int;
  v_occupied int;
  v_final_id uuid;
begin
  select territories.level, territories.capacity into v_input_level, v_capacity
  from territories where territories.id = p_input_territory_id;
  if v_input_level is null then
    raise exception 'Territory not found';
  end if;

  if p_partner_type = 'franchise' then
    if v_input_level <> 'region' then
      raise exception 'A Franchise must be assigned a region';
    end if;
    v_final_id := p_input_territory_id;
  elsif p_partner_type = 'distributor' then
    if v_input_level <> 'city' then
      raise exception 'A Distributor must be assigned a city/municipality';
    end if;
    v_final_id := p_input_territory_id;
  else
    if v_input_level <> 'city' then
      raise exception 'Select the city/municipality the barangay belongs to';
    end if;
    if p_barangay_name is null or length(trim(p_barangay_name)) = 0 then
      raise exception 'Barangay is required for a Reseller';
    end if;
    v_final_id := find_or_create_barangay_territory(p_barangay_name, p_input_territory_id);
    select territories.capacity into v_capacity from territories where territories.id = v_final_id;
  end if;

  if v_capacity is not null then
    select count(*) into v_occupied
    from partners
    where partners.territory_id = v_final_id and partners.status = 'active';

    if v_occupied >= v_capacity then
      raise exception 'This territory is at capacity (% / %)', v_occupied, v_capacity;
    end if;
  end if;

  return v_final_id;
end;
$$;

grant execute on function resolve_and_reserve_territory to anon, authenticated;

-- ---------------------------------------------------------------------
-- apply_for_partner(): Route A (public /reseller form), rebuilt around a
-- real picked territory instead of free-text region/city/barangay -
-- closes the gap flagged since Phase B (spec §19's live-availability
-- check finally applies to the public form too, not just Route B).
-- Signature changes (p_region/p_city/p_barangay text -> p_territory_id/
-- p_barangay_name), so the old signature is dropped first, same as every
-- prior signature change in this project.
-- ---------------------------------------------------------------------

drop function if exists apply_for_partner(text, text, text, text, text, text, text, partner_type);

create or replace function apply_for_partner(
  p_full_name text,
  p_email text,
  p_mobile text,
  p_address text,
  p_partner_type partner_type,
  p_territory_id uuid,
  p_barangay_name text default null
) returns table (
  partner_id uuid,
  status partner_status
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_final_territory_id uuid;
  v_region_name text;
  v_city_name text;
  v_barangay_name text;
  v_new_id uuid;
begin
  v_final_territory_id := resolve_and_reserve_territory(p_partner_type, p_territory_id, p_barangay_name);

  select d.region_name, d.city_name, d.barangay_name
    into v_region_name, v_city_name, v_barangay_name
  from describe_territory_chain(v_final_territory_id) d;

    full_name, email, mobile, address, region, city, barangay,
    partner_type, territory_id, status
  ) values (
    p_full_name, p_email, p_mobile, p_address, v_region_name, v_city_name, v_barangay_name,
    p_partner_type, v_final_territory_id, 'pending'
  )
  returning partners.id into v_new_id;

  return query select v_new_id, 'pending'::partner_status;
end;
$$;

grant execute on function apply_for_partner to anon, authenticated;

-- ---------------------------------------------------------------------
-- onboard_partner(): Route B, rebuilt the same way. Containment (spec
-- §28) now reduces to one shared check for both onboardable roles - the
-- input territory is always a CITY (either directly the new Distributor's
-- territory, or the parent city for a new Reseller's barangay), never a
-- raw barangay id, so there's exactly one comparison per sponsor type
-- instead of the barangay-vs-city-vs-region branching the original Part
-- 2 version needed.
-- ---------------------------------------------------------------------

drop function if exists onboard_partner(text, text, text, text, partner_type, uuid);

create or replace function onboard_partner(
  p_full_name text,
  p_email text,
  p_mobile text,
  p_address text,
  p_partner_type partner_type,
  p_territory_id uuid,
  p_barangay_name text default null
) returns table (partner_id uuid, status partner_status)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller_partner_id uuid;
  v_caller_type partner_type;
  v_caller_status partner_status;
  v_caller_territory_id uuid;
  v_final_territory_id uuid;
  v_region_name text;
  v_city_name text;
  v_barangay_name text;
  v_new_partner_id uuid;
  v_ancestor_region uuid;
begin
  select partners.id, partners.partner_type, partners.status, partners.territory_id
    into v_caller_partner_id, v_caller_type, v_caller_status, v_caller_territory_id
  from partners where partners.user_id = auth.uid();

  if v_caller_partner_id is null then
    raise exception 'Only a signed-in partner can onboard another partner';
  end if;
  if v_caller_status <> 'active' then
    raise exception 'Only an active partner can onboard another partner';
  end if;

  if v_caller_type = 'reseller' then
    raise exception 'Resellers cannot onboard other partners';
  elsif v_caller_type = 'distributor' and p_partner_type <> 'reseller' then
    raise exception 'Distributors can only onboard Resellers';
  elsif v_caller_type = 'franchise' and p_partner_type = 'franchise' then
    raise exception 'Franchises cannot onboard other Franchises';
  end if;

  if v_caller_territory_id is null then
    raise exception 'You must have an assigned territory before onboarding a partner';
  end if;

  if v_caller_type = 'distributor' then
    if p_territory_id <> v_caller_territory_id then
      raise exception 'You can only onboard a Reseller into a barangay within your own city';
    end if;
  elsif v_caller_type = 'franchise' then
    v_ancestor_region := territory_ancestor_region_id(p_territory_id);
    if v_ancestor_region is distinct from v_caller_territory_id then
      raise exception 'You can only onboard a partner into a city or barangay within your own region';
    end if;
  end if;

  v_final_territory_id := resolve_and_reserve_territory(p_partner_type, p_territory_id, p_barangay_name);

  select d.region_name, d.city_name, d.barangay_name
    into v_region_name, v_city_name, v_barangay_name
  from describe_territory_chain(v_final_territory_id) d;

    full_name, email, mobile, address, region, city, barangay,
    partner_type, territory_id, status, parent_partner_id, onboarded_by_partner_id
  ) values (
    p_full_name, p_email, p_mobile, p_address, v_region_name, v_city_name, v_barangay_name,
    p_partner_type, v_final_territory_id, 'pending', v_caller_partner_id, v_caller_partner_id
  )
  returning partners.id into v_new_partner_id;

  return query select v_new_partner_id, 'pending'::partner_status;
end;
$$;

grant execute on function onboard_partner to authenticated;
